SELECT product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MAX(revenue) - MIN(revenue) AS revenue_range, COUNT(*) AS num_store_sales, ROUND(AVG(revenue), 2) AS avg_revenue FROM store_sales GROUP BY product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY num_store_sales DESC;
